# Geometry exports

`app/src/core/stl.ts` exports deterministic binary STL files from the same
pure model-tree mesh used by the viewport. Each geometry-bearing part becomes
its own closed solid, is parsed back, and is validated watertight before the
export tests accept it. The exporter has no runtime dependency and never
mutates the document.

## STEP is deliberately deferred

STEP is not emitted in this release. The current geometry source is a
procedural triangle mesh, not a B-rep model with analytic surfaces, topology,
and sewing operations. Writing a file labelled STEP from that representation
would be misleading and would require either a modeling kernel or a new,
justified B-rep implementation. STL is the honest interoperable output until
that source representation exists.
import { vehicleToMesh, type PartRange } from "./mesh";
import type { Vehicle, VehiclePart } from "./types";

type Vec3 = readonly [number, number, number];

export interface ParsedStl {
  header: Uint8Array;
  triangles: readonly [Vec3, Vec3, Vec3][];
}

export interface PartStl {
  partId: number;
  filename: string;
  bytes: Uint8Array;
}

const sub = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const cross = (a: Vec3, b: Vec3): Vec3 => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
const length = (v: Vec3): number => Math.hypot(v[0], v[1], v[2]);
const normalize = (v: Vec3): Vec3 => {
  const n = length(v);
  return n > 0 ? [v[0] / n, v[1] / n, v[2] / n] : [0, 1, 0];
};
const key = (v: Vec3): string => `${v[0]},${v[1]},${v[2]}`;

function findPart(parts: readonly VehiclePart[], id: number): VehiclePart | undefined {
  for (const part of parts) {
    if (part.id === id) return part;
    const child = findPart(part.children, id);
    if (child) return child;
  }
  return undefined;
}

function shellThicknessM(part: VehiclePart | undefined): number {
  if (!part) return 0.001;
  if (part.kind.type === "fin_set") return Math.max(0.0001, Number(part.kind.thickness_mm) / 1000);
  if (part.kind.type === "body_tube") return Math.max(0.0001, Number(part.kind.wall_mm) / 1000);
  return 0.001;
}

/** Turn one display surface range into a closed, finite-thickness solid.
 * This intentionally consumes `vehicleToMesh`: STL and the R3F viewport
 * share the same model-tree geometry, while the STL path adds the missing
 * back faces and boundary walls required by a printable solid. */
function solidify(
  positions: Float32Array,
  indices: Uint32Array,
  range: PartRange,
  thicknessM: number,
): [Vec3, Vec3, Vec3][] {
  const vertices: Vec3[] = [];
  const ids = new Map<string, number>();
  const faces: number[][] = [];
  const add = (v: Vec3): number => {
    const k = key(v);
    const present = ids.get(k);
    if (present !== undefined) return present;
    const next = vertices.length;
    vertices.push(v);
    ids.set(k, next);
    return next;
  };
  for (let i = range.start; i < range.start + range.count; i += 3) {
    const face = [indices[i], indices[i + 1], indices[i + 2]].map((index) => {
      const at = index * 3;
      return add([positions[at], positions[at + 1], positions[at + 2]]);
    });
    const [a, b, c] = face.map((index) => vertices[index]) as [Vec3, Vec3, Vec3];
    if (length(cross(sub(b, a), sub(c, a))) > 1e-12) faces.push(face);
  }
  if (faces.length === 0) return [];

  const normals: Vec3[] = vertices.map(() => [0, 0, 0]);
  const edges = new Map<string, { a: number; b: number; count: number }>();
  const edge = (a: number, b: number) => {
    const name = a < b ? `${a}:${b}` : `${b}:${a}`;
    const found = edges.get(name);
    if (found) found.count += 1;
    else edges.set(name, { a, b, count: 1 });
  };
  for (const [ia, ib, ic] of faces) {
    const n = cross(sub(vertices[ib], vertices[ia]), sub(vertices[ic], vertices[ia]));
    for (const index of [ia, ib, ic]) {
      const old = normals[index];
      normals[index] = [old[0] + n[0], old[1] + n[1], old[2] + n[2]];
    }
    edge(ia, ib); edge(ib, ic); edge(ic, ia);
  }
  const half = thicknessM / 2;
  const outer = vertices.map((v, i) => {
    const n = normalize(normals[i]);
    return [v[0] + n[0] * half, v[1] + n[1] * half, v[2] + n[2] * half] as Vec3;
  });
  const inner = vertices.map((v, i) => {
    const n = normalize(normals[i]);
    return [v[0] - n[0] * half, v[1] - n[1] * half, v[2] - n[2] * half] as Vec3;
  });
  const triangles: [Vec3, Vec3, Vec3][] = [];
  for (const [a, b, c] of faces) {
    triangles.push([outer[a], outer[b], outer[c]], [inner[c], inner[b], inner[a]]);
  }
  for (const boundary of edges.values()) {
    if (boundary.count !== 1) continue;
    const { a, b } = boundary;
    triangles.push([outer[a], inner[a], inner[b]], [outer[a], inner[b], outer[b]]);
  }
  return triangles;
}

function binaryStl(headerText: string, triangles: readonly [Vec3, Vec3, Vec3][]): Uint8Array {
  const bytes = new Uint8Array(84 + triangles.length * 50);
  bytes.set(new TextEncoder().encode(headerText).slice(0, 80));
  const view = new DataView(bytes.buffer);
  view.setUint32(80, triangles.length, true);
  let offset = 84;
  for (const triangle of triangles) {
    const normal = normalize(cross(sub(triangle[1], triangle[0]), sub(triangle[2], triangle[0])));
    for (const v of [normal, ...triangle]) {
      view.setFloat32(offset, v[0], true); view.setFloat32(offset + 4, v[1], true); view.setFloat32(offset + 8, v[2], true);
      offset += 12;
    }
    view.setUint16(offset, 0, true);
    offset += 2;
  }
  return bytes;
}

export function exportVehicleBinaryStl(vehicle: Vehicle): readonly PartStl[] {
  const mesh = vehicleToMesh(vehicle);
  return mesh.parts.flatMap((range) => {
    const triangles = solidify(mesh.positions, mesh.indices, range, shellThicknessM(findPart(vehicle.parts, range.id)));
    if (triangles.length === 0) return [];
    return [{
      partId: range.id,
      filename: `${vehicle.name.replace(/[^a-z0-9]+/gi, "-").replace(/^-|-$/g, "").toLowerCase() || "vehicle"}-part-${range.id}.stl`,
      bytes: binaryStl(`Ascent part ${range.id}`, triangles),
    }];
  });
}

export function parseBinaryStl(bytes: Uint8Array): ParsedStl {
  if (bytes.byteLength < 84) throw new Error("binary STL header is truncated");
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const count = view.getUint32(80, true);
  const expected = 84 + count * 50;
  if (bytes.byteLength !== expected) throw new Error(`binary STL length ${bytes.byteLength} does not match declared triangle count ${count}`);
  const triangles: [Vec3, Vec3, Vec3][] = [];
  let offset = 84;
  for (let i = 0; i < count; i++) {
    offset += 12; // stored normal; recompute when validating
    const read = (): Vec3 => {
      const v: Vec3 = [view.getFloat32(offset, true), view.getFloat32(offset + 4, true), view.getFloat32(offset + 8, true)];
      offset += 12;
      return v;
    };
    triangles.push([read(), read(), read()]);
    offset += 2;
  }
  return { header: bytes.slice(0, 80), triangles };
}

export function assertWatertight(stl: ParsedStl): void {
  const edges = new Map<string, number>();
  const add = (a: Vec3, b: Vec3) => {
    const ka = key(a); const kb = key(b);
    const edge = ka < kb ? `${ka}|${kb}` : `${kb}|${ka}`;
    edges.set(edge, (edges.get(edge) ?? 0) + 1);
  };
  for (const triangle of stl.triangles) {
    if (triangle.some((v) => !v.every(Number.isFinite))) throw new Error("STL has non-finite vertex");
    if (length(cross(sub(triangle[1], triangle[0]), sub(triangle[2], triangle[0]))) <= 1e-12) throw new Error("STL has degenerate triangle");
    add(triangle[0], triangle[1]); add(triangle[1], triangle[2]); add(triangle[2], triangle[0]);
  }
  if (stl.triangles.length === 0) throw new Error("STL has no triangles");
  if ([...edges.values()].some((count) => count !== 2)) throw new Error("STL is not watertight");
}
//! Flight-readiness report (v0.5 Step 6): a deterministic Markdown
//! artifact synthesized from the document's stored studies plus an
//! optional structural/rule review. Two disciplines make it trustworthy:
//!
//! - **Provenance.** Every performance number is drawn from a study's
//!   stored results and stamped with that study's input hash. A reader can
//!   tie any figure back to the exact (vehicle, design, atmosphere, study)
//!   that produced it — the same content hash the job runner records.
//! - **Honesty about staleness.** A study whose stored hash no longer
//!   matches the current inputs renders `STALE`, showing both hashes, so
//!   the report never presents an out-of-date number as current.
//!
//! The generator is a pure function of its inputs: no clock, no
//! randomness, iteration in document order. Same inputs → byte-identical
//! Markdown, so the report itself is a determinism artifact.
//!
//! Structural margins and rule compliance come from an optional
//! [`ReviewReport`]. When it is absent (Codex's structural pack has not
//! run yet, or the caller chose not to compute it), those sections
//! degrade to an explicit "not yet computed" line rather than inventing
//! numbers or omitting the section silently.

use crate::document::Document;
use crate::review_ipc::ReviewReport;
use crate::study::{study_input_hash, Study, StudyKind};
use std::fmt::Write as _;

/// Provenance status of a study's stored results against current inputs.
enum Freshness {
    /// No results stored — the study has never run.
    NotRun,
    /// Stored hash matches current inputs.
    Current(String),
    /// Stored hash no longer matches (stored, current).
    Stale(String, String),
}

fn freshness(doc: &Document, study: &Study) -> Freshness {
    let current = study_input_hash(&doc.vehicle, &doc.design, doc.atmosphere.as_ref(), study);
    match &study.results {
        None => Freshness::NotRun,
        Some(r) if r.input_hash == current => Freshness::Current(r.input_hash.clone()),
        Some(r) => Freshness::Stale(r.input_hash.clone(), current),
    }
}

/// First 12 hex chars — enough to identify a hash in prose without the
/// full 64-char string dominating the line.
fn short(hash: &str) -> &str {
    &hash[..hash.len().min(12)]
}

fn kind_label(kind: &StudyKind) -> String {
    match kind {
        StudyKind::SingleFlight => "single flight".into(),
        StudyKind::Dispersion { flights } => format!("dispersion, {flights} flights"),
        StudyKind::MotorTrade { candidates } => {
            format!("motor trade ({} candidates)", candidates.len())
        }
        StudyKind::StabilitySweep {
            param,
            from,
            to,
            steps,
        } => {
            format!("stability sweep of {param}: {from} → {to} in {steps}")
        }
    }
}

/// Pull a finite f64 field out of a study's result payload; `None` when
/// absent or non-finite so the report can say "—" instead of "NaN".
fn num(data: &serde_json::Value, key: &str) -> Option<f64> {
    data.get(key)
        .and_then(|v| v.as_f64())
        .filter(|v| v.is_finite())
}

fn fmt_m(value: Option<f64>) -> String {
    match value {
        Some(v) => format!("{v:.1} m"),
        None => "—".into(),
    }
}

/// Render the description of the design's recovery configuration.
fn recovery_line(doc: &Document) -> String {
    let chute = &doc.design.chute;
    if !chute.enabled {
        return "none (ballistic descent)".into();
    }
    match chute.main_deploy_altitude_m {
        None => format!(
            "single-deploy · {:.0} cm main @ Cd {}",
            chute.diameter_cm, chute.cd
        ),
        Some(deploy_m) => {
            let drogue = match (chute.drogue_diameter_cm, chute.drogue_cd) {
                (Some(d), Some(cd)) => format!("{d:.0} cm drogue @ Cd {cd} at apogee"),
                _ => "free descent".into(),
            };
            format!(
                "dual-deploy · {drogue}, {:.0} cm main @ Cd {} at {deploy_m:.0} m",
                chute.diameter_cm, chute.cd
            )
        }
    }
}

/// Build the flight-readiness report as Markdown. `review` supplies
/// structural margins and rule compliance; pass `None` to render those
/// sections as not-yet-computed.
pub fn flight_readiness_markdown(doc: &Document, review: Option<&ReviewReport>) -> String {
    let mut out = String::new();
    let d = &doc.design;

    let _ = writeln!(out, "# Flight-Readiness Report: {}", d.name);
    out.push('\n');

    // ---- Configuration ----
    let _ = writeln!(out, "## Configuration");
    out.push('\n');
    let _ = writeln!(out, "- Motor: {}", d.motor_designation);
    let _ = writeln!(out, "- Dry mass: {:.1} g", d.dry_mass_g);
    let _ = writeln!(out, "- Diameter: {:.1} mm", d.diameter_mm);
    let _ = writeln!(out, "- Drag coefficient: {}", d.cd);
    let _ = writeln!(out, "- Rail length: {:.2} m", d.rail_length_m);
    let _ = writeln!(out, "- Recovery: {}", recovery_line(doc));
    let atmosphere = match &doc.atmosphere {
        Some(profile) => format!(
            "imported profile \"{}\" ({} layers)",
            profile.name,
            profile.layers.len()
        ),
        None => "1976 US Standard Atmosphere (analytic)".into(),
    };
    let _ = writeln!(out, "- Atmosphere: {atmosphere}");
    out.push('\n');

    // ---- Studies ----
    let _ = writeln!(out, "## Studies");
    out.push('\n');
    if doc.studies.is_empty() {
        let _ = writeln!(
            out,
            "No studies defined. Create and run a study to populate performance numbers."
        );
        out.push('\n');
    }
    let mut any_stale = false;
    let mut any_not_run = false;
    for study in &doc.studies {
        let _ = writeln!(out, "### {} — {}", study.name, kind_label(&study.kind));
        let _ = writeln!(out, "engine `{}` · seed `{}`", study.engine, study.seed);
        out.push('\n');
        match freshness(doc, study) {
            Freshness::NotRun => {
                any_not_run = true;
                let _ = writeln!(out, "- Status: **NOT RUN** — no stored results.");
            }
            Freshness::Current(hash) => {
                let _ = writeln!(out, "- Status: **CURRENT** · provenance `{}`", short(&hash));
            }
            Freshness::Stale(stored, current) => {
                any_stale = true;
                let _ = writeln!(
                    out,
                    "- Status: **STALE** · stored `{}` ≠ current `{}` — re-run before trusting these numbers.",
                    short(&stored),
                    short(&current)
                );
            }
        }
        if let Some(results) = &study.results {
            render_result_numbers(&mut out, study, &results.data);
        }
        out.push('\n');
    }

    // ---- Structural margins ----
    let _ = writeln!(out, "## Structural Margins");
    out.push('\n');
    match review {
        None => {
            let _ = writeln!(out, "Not yet computed — run a structural review to populate fin-flutter and airframe margins.");
        }
        Some(report) if report.review.structural_checks.is_empty() => {
            let _ = writeln!(
                out,
                "No structural checks available for this configuration."
            );
        }
        Some(report) => {
            let _ = writeln!(out, "| Check | Value | Limit | Margin | Status | Source |");
            let _ = writeln!(out, "|---|---|---|---|---|---|");
            for check in &report.review.structural_checks {
                let _ = writeln!(
                    out,
                    "| {} | {:.3} {} | {:.3} {} | {:+.3} | {} | {} |",
                    check.label,
                    check.value,
                    check.units,
                    check.limit,
                    check.units,
                    check.margin,
                    if check.pass { "PASS" } else { "**FAIL**" },
                    check.source,
                );
            }
        }
    }
    out.push('\n');

    // ---- Rule compliance ----
    let _ = writeln!(out, "## Rule Compliance");
    out.push('\n');
    match review {
        None => {
            let _ = writeln!(
                out,
                "Not yet computed — run a flight review against the rule pack."
            );
        }
        Some(report) => {
            let _ = writeln!(out, "| Rule | Measured | Required | Status | Citation |");
            let _ = writeln!(out, "|---|---|---|---|---|");
            for check in &report.review.checks {
                let _ = writeln!(
                    out,
                    "| {} | {:.3} | {:.3} | {} | {} |",
                    check.description,
                    check.measured,
                    check.required,
                    if check.pass { "PASS" } else { "**FAIL**" },
                    check.citation,
                );
            }
            let _ = writeln!(
                out,
                "\nTarget apogee {:.1} m (±{:.1} m): {}. Mission feasible: {}.",
                report.target_apogee_m,
                report.target_tolerance_m,
                if report.target_met {
                    "met"
                } else {
                    "**missed**"
                },
                if report.mission_feasible {
                    "yes"
                } else {
                    "**no**"
                },
            );
        }
    }
    out.push('\n');

    // ---- Verdict ----
    let _ = writeln!(out, "## Verdict");
    out.push('\n');
//! `cargo xtask <task>` — workspace automation as plain Rust.
//!
//! Tasks:
//! - `test`     full gate: Rust workspace tests + frontend typecheck + vitest
//! - `audit`    cargo audit (advisory database; requires cargo-audit)
//! - `vet`      cargo vet (supply-chain review; requires cargo-vet)
//! - `ci`       everything above, in order — what CI runs

//! Workspace maintenance commands:
//! - `test`     run metadata, Rust, frontend typecheck, and frontend tests
//! - `metadata` verify every workspace package declares a license
//! - `audit`    cargo audit (advisory database; requires cargo-audit)
//! - `vet`      cargo vet (supply-chain review; requires cargo-vet)
//! - `ci`       everything above, in order

use std::path::{Path, PathBuf};
use std::process::Command;

fn workspace_root() -> PathBuf {
    // xtask always lives at <root>/xtask.
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("xtask sits in the workspace root")
        .to_path_buf()
}

fn run(mut cmd: Command, what: &str) -> Result<(), String> {
    let status = cmd
        .status()
        .map_err(|e| format!("{what}: failed to launch: {e}"))?;
    if status.success() {
        Ok(())
    } else {
        Err(format!("{what}: exited with {status}"))
    }
}

fn cargo(args: &[&str], what: &str) -> Result<(), String> {
    let mut cmd = Command::new(env!("CARGO"));
    cmd.args(args).current_dir(workspace_root());
    run(cmd, what)
}

fn npm(args: &[&str], what: &str) -> Result<(), String> {
    let mut cmd = Command::new("npm");
    cmd.args(args).current_dir(workspace_root().join("app"));
    run(cmd, what)
}

fn task_metadata() -> Result<(), String> {
    let output = Command::new(env!("CARGO"))
        .args(["metadata", "--no-deps", "--format-version", "1"])
        .current_dir(workspace_root())
        .output()
        .map_err(|error| format!("cargo metadata: failed to launch: {error}"))?;
    if !output.status.success() {
        return Err(format!("cargo metadata: exited with {}", output.status));
    }
    let metadata = String::from_utf8(output.stdout)
        .map_err(|error| format!("cargo metadata emitted non-UTF-8: {error}"))?;
    if metadata.contains("\"license\":null") {
        return Err("cargo metadata: a workspace package has no license".into());
    }
    Ok(())
}

fn task_test() -> Result<(), String> {
    task_metadata()?;
    // Keep the agent-contract golden transcripts visible in CI rather than
    // relying on their inclusion as an incidental workspace test target.
    cargo(
        &["test", "-p", "ascent-mcp", "--test", "evals"],
        "MCP agent evals",
    )?;
    cargo(&["test", "--workspace"], "cargo test")?;
    npm(&["run", "typecheck"], "frontend typecheck")?;
    npm(&["test"], "vitest")
}

fn task_audit() -> Result<(), String> {
    cargo(
        &["audit"],
        "cargo audit (install: cargo install cargo-audit)",
    )
}

fn task_vet() -> Result<(), String> {
    cargo(
        &["vet", "--locked"],
        "cargo vet (install: cargo install cargo-vet)",
    )
}

fn main() -> std::process::ExitCode {
    let task = std::env::args().nth(1).unwrap_or_default();
    let outcome = match task.as_str() {
        "test" => task_test(),
        "metadata" => task_metadata(),
        "audit" => task_audit(),
        "vet" => task_vet(),
        "ci" => task_test()
            .and_then(|()| task_audit())
            .and_then(|()| task_vet()),
        _ => Err("usage: cargo xtask <test|metadata|audit|vet|ci>".into()),
    };
    match outcome {
        Ok(()) => std::process::ExitCode::SUCCESS,
        Err(message) => {
            eprintln!("xtask: {message}");
            std::process::ExitCode::FAILURE
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_workspace_package_declares_a_license() {
        task_metadata().unwrap();
    }
}

