                    format!("task {} is not completed ({status:?})", request.task_id),
                    None,
                )),
            }
        }
    }

    fn cancel_task(
        &self,
        request: CancelTaskParams,
        _context: rmcp::service::RequestContext<rmcp::RoleServer>,
    ) -> impl Future<Output = Result<CancelTaskResult, McpError>> + Send + '_ {
